const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Structured logging utility for crypto operations
class CryptoAuditLogger {
  constructor(logPath) {
    this.logPath = logPath;
    this.buffer = [];
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  formatEntry(level, component, message, metadata) {
    const timestamp = new Date().toISOString();
    const sanitized = this._sanitizeMetadata(metadata);
    return JSON.stringify({
      timestamp,
      level,
      component,
      message,
      ...sanitized
    });
  }

  _sanitizeMetadata(metadata) {
    if (!metadata) return {};
    const clean = {};
    for (const [key, value] of Object.entries(metadata)) {
      if (typeof value === 'string') {
        clean[key] = value.replace(/[\x00-\x1f]/g, '');
      } else if (typeof value === 'number' || typeof value === 'boolean') {
        clean[key] = value;
      } else if (Buffer.isBuffer(value)) {
        clean[key] = value.toString('hex').substring(0, 64);
      }
    }
    return clean;
  }

  log(level, component, message, metadata) {
    const entry = this.formatEntry(level, component, message, metadata);
    this.buffer.push(entry);
  }

  flush() {
    if (this.buffer.length === 0) return;
    const data = this.buffer.join('\n') + '\n';
    fs.appendFileSync(this.logPath, data);
    this.buffer = [];
  }

  destroy() {
    clearInterval(this.flushInterval);
    this.flush();
  }
}

// Certificate/key file processor
class CryptoFileProcessor {
  constructor(logger) {
    this.logger = logger;
    this.supportedFormats = ['pem', 'der', 'p12'];
  }

  detectFormat(buffer, filename) {
    const ext = path.extname(filename).toLowerCase().slice(1);
    if (this.supportedFormats.includes(ext)) return ext;
    if (buffer.slice(0, 5).toString() === '-----') return 'pem';
    return 'unknown';
  }

  extractSubjectFromPEM(pemContent) {
    const lines = pemContent.toString().split('\n');
    const headerLine = lines.find(l => l.startsWith('subject='));
    return headerLine ? headerLine.substring(8) : 'unknown';
  }

  computeFingerprint(buffer, algorithm = 'sha256') {
    return crypto.createHash(algorithm).update(buffer).digest('hex');
  }

  async processUpload(fileBuffer, filename, uploaderId) {
    const format = this.detectFormat(fileBuffer, filename);
    const fingerprint = this.computeFingerprint(fileBuffer);

    this.logger.log('info', 'crypto-processor', 'Processing uploaded crypto material', {
      filename: filename,
      format: format,
      size: fileBuffer.length,
      fingerprint: fingerprint,
      uploaderId: uploaderId
    });

    if (format === 'unknown') {
      this.logger.log('warn', 'crypto-processor', 'Unsupported format detected', {
        filename: filename,
        uploaderId: uploaderId
      });
      return { success: false, error: 'Unsupported format' };
    }

    const result = await this._processByFormat(fileBuffer, format, filename);
    return result;
  }

  async _processByFormat(buffer, format, filename) {
    switch (format) {
      case 'pem':
        return this._processPEM(buffer, filename);
      case 'der':
        return this._processDER(buffer, filename);
      case 'p12':
        return this._processP12(buffer, filename);
      default:
        return { success: false, error: 'Internal error' };
    }
  }

  _processPEM(buffer, filename) {
    const content = buffer.toString('utf-8');
    const subject = this.extractSubjectFromPEM(content);
    const certType = this._detectCertType(content);

    this.logger.log('info', 'pem-handler', 'Processed PEM file', {
      filename, certType, subject
    });

    return {
      success: true,
      format: 'pem',
      certType,
      subject,
      fingerprint: this.computeFingerprint(buffer)
    };
  }

  _processDER(buffer, filename) {
    const fingerprint = this.computeFingerprint(buffer);
    this.logger.log('info', 'der-handler', 'Processed DER file', {
      filename, fingerprint, size: buffer.length
    });
    return { success: true, format: 'der', fingerprint };
  }

  _processP12(buffer, filename) {
    const fingerprint = this.computeFingerprint(buffer);
    this.logger.log('info', 'p12-handler', 'Processed PKCS12 file', {
      filename, fingerprint, size: buffer.length
    });
    return { success: true, format: 'p12', fingerprint };
  }

  _detectCertType(pemContent) {
    if (pemContent.includes('BEGIN CERTIFICATE')) return 'certificate';
    if (pemContent.includes('BEGIN PRIVATE KEY')) return 'private-key';
    if (pemContent.includes('BEGIN PUBLIC KEY')) return 'public-key';
    if (pemContent.includes('BEGIN RSA PRIVATE KEY')) return 'rsa-private-key';
    return 'unknown';
  }
}

module.exports = { CryptoAuditLogger, CryptoFileProcessor };
